async function loadTopic(id) {
  try {
    const res = await fetch(`/content/${id}.json`);
    if (!res.ok) throw new Error('Not found');
    return await res.json();
  } catch (err) {
    console.error('Failed to load topic', err);
    return null;
  }
}

